<script lang="ts">import {onMount,getContext} from 'svelte';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createCycleCountApprovalsState} from '../state/cycleCountApprovalsState.svelte';const i18n=getContext<I18nState>('i18n');const vm=createCycleCountApprovalsState();onMount(()=>{void vm.load();});</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{i18n.t('Aprobación de conteos')}</h1><p>{i18n.t('Revisa diferencias agrupadas por conteo y ubicación. Las aprobaciones aplican los ajustes al inventario.')}</p></div><button onclick={()=>void vm.load()}>{i18n.t('Actualizar')}</button></header>{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else if vm.groups.length===0}<p class="empty">{i18n.t('No hay ajustes pendientes de aprobación.')}</p>{:else}<div class="sort"><span>{i18n.t('Ordenar por')}</span><button class:active={vm.sortBy==='count'} onclick={()=>vm.setSort('count')}>{i18n.t('Número de conteo')}</button><button class:active={vm.sortBy==='bin'} onclick={()=>vm.setSort('bin')}>{i18n.t('Ubicación')}</button></div>{#each vm.sortedGroups as g (g.cycleCountId)}<article class="card"><header><strong>{g.cycleCountId ? 'Conteo #' + g.cycleCountId : i18n.t('Sin conteo asociado')} · {g.binCode}</strong><span>{g.adjustments.length} {i18n.t('diferencias')}</span></header><div class="table-wrap"><table><thead><tr><th>SKU</th><th>{i18n.t('Producto')}</th><th>{i18n.t('Esperado')}</th><th>{i18n.t('Contado')}</th><th>{i18n.t('Variación')}</th><th>{i18n.t('Contado por')}</th><th>{i18n.t('Decisión')}</th></tr></thead><tbody>{#each g.adjustments as a (a.adjustmentId)}<tr><td>{a.sku??'—'}</td><td>{a.itemName??a.itemId}</td><td>{a.expectedQuantity??'—'}</td><td>{a.countedQuantity??'—'}</td><td class:negative={a.quantityChange<0} class:positive={a.quantityChange>0}>{a.quantityChange>0?'+':''}{a.quantityChange}</td><td>{a.adjustedBy}</td><td><label><input type="radio" name={'decision-'+a.adjustmentId} checked={vm.decisions[a.adjustmentId]==='approve'} onchange={()=>vm.setDecision(a.adjustmentId,'approve')}/>{i18n.t('Aprobar')}</label><label><input type="radio" name={'decision-'+a.adjustmentId} checked={vm.decisions[a.adjustmentId]==='reject'} onchange={()=>vm.setDecision(a.adjustmentId,'reject')}/>{i18n.t('Rechazar')}</label></td></tr>{/each}</tbody></table></div><footer><button class="primary" disabled={vm.saving} onclick={()=>void vm.submit(g)}>{i18n.t('Enviar decisiones')}</button><button onclick={()=>vm.setAll(g,'approve')}>{i18n.t('Aprobar todo')}</button><button onclick={()=>vm.setAll(g,'reject')}>{i18n.t('Rechazar todo')}</button></footer></article>{/each}{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}.primary{background:var(--navy);color:white;border-color:var(--navy)}.sort{display:flex;align-items:center;gap:.5rem;margin:1rem 0;color:var(--slate);font-size:.8rem}.sort .active{background:var(--navy);color:white}.card{border:1px solid var(--line);border-radius:12px;background:var(--card);padding:1rem;margin:1rem 0}.card header{margin:0 0 .7rem}.card header span{color:var(--slate);font-size:.8rem}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.82rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.68rem;text-transform:uppercase}td label{margin-right:.7rem;font-size:.78rem}td input{margin-right:.25rem}.negative{color:var(--danger)}.positive{color:var(--success)}footer{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.8rem}.error{color:var(--danger)}.empty{color:var(--slate);padding:2rem 0}</style>